mapper.update:
UPDATE COMM_RD_EMPLOYEE
BADGE=#{badge}, DEPID=#{depid},
WHERE BADGE=#{badge}

mapper.select:
SELECT C.EMPNAME USERNAME, C.BADGE, g.MONTH_OF_YEAR, D.DEPID, D.LOCATION CHARGENAME, G.EID_CODE, SUM(G.ATTENDANCE_TIME) AS sum_Month FROM PPM.COMM_RD_EMPLOYEE C LEFT JOIN COMM_RD_DEPARTMENT D ON C.DEPID = D.DEPID LEFT JOIN ( SELECT EID_CODE, PROJECT_CODE, EID, ISDISABLED , CREATE_DATE FROM PPM.RD_PROJECT_EMPLOYEE WHERE ISDISABLED = '0') E ON C.EID = E.EID LEFT JOIN RD_PROJECT T ON E.PROJECT_CODE = T.PROJECT_CODE LEFT JOIN RD_PROJECT_CONFIG G ON G.EID_CODE = E.EID_CODE WHERE T.PROJECT_STATE IN ('1', '2') AND T.DELETED = '0' AND (c.ARRIVAL_TIME <= #{lastDay} or c.ARRIVAL_TIME is null) and (c.LEAVE_TIME > #{firstDay} or (c.LEAVE_TIME is null and c.empstatus = '0'))
AND TO_CHAR(g.CALENDAR_DATE,'yyyy-MM') = #{attendanceDate}
AND g.ATTENDANCE_ORNO = '1' GROUP BY C.EMPNAME,G.EID_CODE,C.BADGE，g.MONTH_OF_YEAR, D.DEPID, D.LOCATION ORDER BY C.BADGE
